using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; using ProMaxx2.QA.Domain.Execution; using ProMaxx2.QA.Domain.Identity;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class QaSkillMatrixEntryConfiguration : IEntityTypeConfiguration<QaSkillMatrixEntry> { public void Configure(EntityTypeBuilder<QaSkillMatrixEntry> b) { b.ToTable("QaSkillMatrixEntries"); b.HasKey(x => x.QaSkillMatrixEntryId); b.Property(x => x.SkillCode).HasMaxLength(100).IsRequired(); b.HasIndex(x => new { x.UserId, x.SkillCode }).IsUnique(); b.HasOne<User>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Cascade); } }
public sealed class QaAvailabilityConfiguration : IEntityTypeConfiguration<QaAvailability> { public void Configure(EntityTypeBuilder<QaAvailability> b) { b.ToTable("QaAvailabilities"); b.HasKey(x => x.QaAvailabilityId); b.Property(x => x.Status).HasMaxLength(30).IsRequired(); b.HasIndex(x => new { x.UserId, x.Date }).IsUnique(); b.HasOne<User>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Cascade); } }
public sealed class AssignmentPreviewConfiguration : IEntityTypeConfiguration<AssignmentPreview> { public void Configure(EntityTypeBuilder<AssignmentPreview> b) { b.ToTable("AssignmentPreviews"); b.HasKey(x => x.AssignmentPreviewId); b.Property(x => x.Version).HasMaxLength(64).IsRequired(); b.Property(x => x.Status).HasMaxLength(20).IsRequired(); b.HasOne<TestCycle>().WithMany().HasForeignKey(x => x.TestCycleId).OnDelete(DeleteBehavior.Cascade); } }
public sealed class AssignmentHistoryConfiguration : IEntityTypeConfiguration<AssignmentHistory> { public void Configure(EntityTypeBuilder<AssignmentHistory> b) { b.ToTable("AssignmentHistories"); b.HasKey(x => x.AssignmentHistoryId); b.Property(x => x.Reason).HasMaxLength(1000).IsRequired(); b.Property(x => x.Action).HasMaxLength(40).IsRequired(); b.Property(x => x.AlgorithmVersion).HasMaxLength(40).IsRequired(); b.HasOne(x => x.TestCycleCase).WithMany().HasForeignKey(x => x.TestCycleCaseId).OnDelete(DeleteBehavior.Cascade); } }
